using System.Diagnostics;using System.Globalization;using System.Text.Json;using InduForge.Collector.Adapters.Hsl;using InduForge.Collector.Contracts;
namespace InduForge.Collector.Drivers.Turck;
public sealed class TurckReaderDriver:IIndustrialDriver,IConnectionSessionDriver,IPointReader
{
 private readonly IHslSpecializedNetworkClientFactory _factory;public TurckReaderDriver():this(new HslSpecializedNetworkClientFactory()){}internal TurckReaderDriver(IHslSpecializedNetworkClientFactory factory)=>_factory=factory;public DriverDescriptor Descriptor{get;}=new("turck","turck.reader-tcp","1.0.0",[1],[DriverOperations.ConnectionTest,DriverOperations.ConnectionOpen,DriverOperations.ConnectionClose,DriverOperations.PointRead]);
 public async Task<ConnectionTestResult> TestConnectionAsync(ConnectionProfile profile,CancellationToken cancellationToken){var watch=Stopwatch.StartNew();await using var session=await OpenSessionAsync(profile,cancellationToken);watch.Stop();return new(session.IsConnected,watch.Elapsed,session.ServerName,[]);}public async Task<IIndustrialConnectionSession> OpenSessionAsync(ConnectionProfile profile,CancellationToken cancellationToken){var options=TurckOptions.Parse(profile);var client=_factory.Create(options.ToHslOptions());var result=await client.ConnectAsync(cancellationToken);if(!result.Succeeded){await client.DisposeAsync();throw new TurckDriverException(result.ErrorCode??"TURCK_CONNECT_FAILED",result.ErrorMessage??"无法连接 Turck Reader",result.Retryable);}return new Session(client,$"{options.Host}:{options.Port}");}public async Task<ReadResult> ReadAsync(ConnectionProfile profile,ReadRequest request,CancellationToken cancellationToken){await using var session=await OpenSessionAsync(profile,cancellationToken);return await((IPointReaderSession)session).ReadAsync(request,cancellationToken);}
 private sealed class Session(IHslSpecializedNetworkClient client,string serverName):IIndustrialConnectionSession,IPointReaderSession{public bool IsConnected=>client.IsConnected;public string? ServerName{get;}=serverName;public async Task<ReadResult> ReadAsync(ReadRequest request,CancellationToken token){var at=DateTimeOffset.UtcNow;var values=new PointReadValue[request.Points.Count];for(var index=0;index<request.Points.Count;index++){var point=request.Points[index];try{var address=TurckAddress.Parse(point);var result=await client.ReadAsync(address.ToRequest(),token);values[index]=result.Succeeded?new(point.Key,true,result.Value,point.DataType,"Good",at,at,null,null):Fail(point,result.ErrorCode??"TURCK_READ_FAILED",result.ErrorMessage??"Turck 变量读取失败");}catch(TurckDriverException exception){values[index]=Fail(point,exception.Code,exception.Message);}}return new(values,[]);}public ValueTask DisposeAsync()=>client.DisposeAsync();private static PointReadValue Fail(PointReadRequest point,string code,string message)=>new(point.Key,false,null,point.DataType,"Bad",null,null,code,message);}
}
internal sealed record TurckOptions(string Host,int Port,int ConnectTimeoutMs,int ReceiveTimeoutMs){public HslSpecializedNetworkClientOptions ToHslOptions()=>new(HslSpecializedNetworkProtocol.TurckReader,Host,Port,ConnectTimeoutMs,ReceiveTimeoutMs);public static TurckOptions Parse(ConnectionProfile profile){if(!string.Equals(profile.ProtocolFamily,"turck",StringComparison.OrdinalIgnoreCase)||profile.Config.ValueKind!=JsonValueKind.Object)throw Invalid("CONFIG","Turck Reader 连接配置无效");var host=Text(profile.Config,"host")?.Trim();if(string.IsNullOrWhiteSpace(host)||host.Contains("://",StringComparison.Ordinal))throw Invalid("HOST","Turck 设备 IP / 主机名无效");var port=Integer(profile.Config,"port")??5500;if(port is <1 or >65535)throw Invalid("PORT","Turck 端口必须在 1 到 65535 之间");return new(host,port,Timeout(profile.Config,"connectTimeoutMs",5000),Timeout(profile.Config,"receiveTimeoutMs",10000));}private static int Timeout(JsonElement config,string name,int fallback){var value=Integer(config,name)??fallback;if(value is <100 or >120000)throw Invalid("TIMEOUT","Turck 超时必须在 100 到 120000 毫秒之间");return value;}private static string? Text(JsonElement config,string name)=>config.TryGetProperty(name,out var value)&&value.ValueKind==JsonValueKind.String?value.GetString():null;private static int? Integer(JsonElement config,string name)=>config.TryGetProperty(name,out var value)&&value.TryGetInt32(out var result)?result:null;private static TurckDriverException Invalid(string part,string message)=>new($"TURCK_{part}_INVALID",message,false);}
internal sealed record TurckAddress(string Address,HslValueType DataType,int ElementCount){public static TurckAddress Parse(PointReadRequest point){if(point.Address.ValueKind!=JsonValueKind.Object||!point.Address.TryGetProperty("address",out var value)||value.ValueKind!=JsonValueKind.String)throw Invalid();var text=value.GetString()?.Trim()??string.Empty;if(!ulong.TryParse(text,NumberStyles.None,CultureInfo.InvariantCulture,out var offset)||point.ElementCount is <1 or >65535)throw Invalid();return new(offset.ToString(CultureInfo.InvariantCulture),Type(point.DataType),point.ElementCount);}public HslSpecializedNetworkReadRequest ToRequest()=>new(Address,DataType,ElementCount);private static HslValueType Type(string value)=>value switch{"bool"=>HslValueType.Boolean,"int8"=>HslValueType.Signed8,"uint8"=>HslValueType.Unsigned8,"int16"=>HslValueType.Signed16,"uint16"=>HslValueType.Unsigned16,"int32"=>HslValueType.Signed32,"uint32"=>HslValueType.Unsigned32,"int64"=>HslValueType.Signed64,"uint64"=>HslValueType.Unsigned64,"float32"=>HslValueType.SinglePrecision,"float64"=>HslValueType.DoublePrecision,"string"=>HslValueType.Text,"bytes"=>HslValueType.Binary,_=>throw new TurckDriverException("TURCK_DATA_TYPE_UNSUPPORTED","Turck 数据类型不受支持",false)};private static TurckDriverException Invalid()=>new("TURCK_ADDRESS_INVALID","Turck Reader 地址必须是非负数字偏移",false);}
internal sealed class TurckDriverException(string code,string message,bool retryable):Exception(message){public string Code{get;}=code;public bool Retryable{get;}=retryable;}
